function nano_updateFolder(b,c,a){document.getElementById("id_folder").value=c;document.getElementById("foldername").value=a;$("#treeview_inner a").removeClass("active");b.classList.add("active")}function nano_initFolder(a){$("#treeview_inner a").removeClass("active");var b=$("#treeview_node"+a+" a")[1];if(b){b.classList.add("active")}}var sliders={};var clrs={};function uiReset(){resetSliders();resetColors()}function resetSliders(){for(var b in sliders){var a=sliders[b];$("#"+b).slider("value",a)}}function resetColors(){for(var b in clrs){var a=clrs[b];if(jQuery.fn.spectrum){jQuery("#"+b).spectrum("set",a)}else{jQuery("#"+b).val(a)}}};